/**
 * Unit tests for UniformRealDistribution#isSupportUpperBoundInclusive
 */
public class UniformRealDistribution_isSupportUpperBoundInclusive_TriageGen1Test {

    @Test
    public void testIsSupportUpperBoundInclusive_DefaultConstructor() {
        // The default constructor uses standard bounds. 
        // Based on the provided implementation, the method always returns false.
        UniformRealDistribution distribution = new UniformRealDistribution();
        assertFalse("The upper bound should not be inclusive for a default UniformRealDistribution", 
            distribution.isSupportUpperBoundInclusive());
    }






}

