public class UniformRealDistribution_isSupportUpperBoundInclusive_TriageGen1Test {







    @Test
    public void testIsSupportUpperBoundInclusive_WithRandomGenerator() {
        // Testing with a RandomGenerator.
        org.apache.commons.math3.random.JDKRandomGenerator rng = new org.apache.commons.math3.random.JDKRandomGenerator();
        UniformRealDistribution distribution = new UniformRealDistribution(rng, 0.0, 1.0, 1e-12);
